private readonly object gate = new();
private readonly Dictionary<string, Entry> cache = new();

public Entry Find(string key) {
    lock (gate) {                       // reentrant monitor, one acquisition
        return FindImpl(key);
    }
}

private Entry FindImpl(string key) =>   // assumes gate is held
    cache.TryGetValue(key, out var e) ? e : InsertImpl(key);
